with base as (select *, coalesce(merchant, 'unassigned') as merchant_filled, case when amount >= 4200 then 'High' when amount >= 1100 then 'Medium' else 'Low' end as amount_tier from transactions where merchant is not null), with_prev as (select *, lag(txn_time) over (partition by account_id order by txn_time asc, id asc) as prev_txn_time from base), with_gaps as (select *, case when prev_txn_time is null or txn_time > prev_txn_time + interval 7 days then 1 else 0 end as session_start_flag from with_prev), islands as (select *, sum(session_start_flag) over (partition by account_id order by txn_time asc, id asc rows between unbounded preceding and current row) as island_id from with_gaps) select merchant, count(*) as cnt, (unix_timestamp(max(txn_time)) - unix_timestamp(min(txn_time))) / 60 as span_minutes, sum(case when merchant = 'Shell' then island_id else 0 end) as shell_island_id from islands group by merchant
